class Solution {
    public int rearrangeSticks(int n, int k) {
        long MOD = 1_000_000_007L;
        long[] dp = new long[k + 1];
        dp[1] = 1;

        for (int i = 2; i <= n; ++i) {
            long[] nextDp = new long[k + 1];
            for (int j = 1; j <= Math.min(i, k); ++j) {
                nextDp[j] = (dp[j - 1] + (long)(i - 1) * dp[j]) % MOD;
            }
            dp = nextDp;
        }
        return (int)dp[k];
    }
}

