var rearrangeSticks = function(n, k) {
    const MOD = 1000000007n;
    let dp = Array(k + 1).fill(0n);
    dp[1] = 1n;

    for (let i = 2; i <= n; ++i) {
        const nextDp = Array(k + 1).fill(0n);
        const limit = Math.min(i, k);
        for (let j = 1; j <= limit; ++j) {
            nextDp[j] = (dp[j - 1] + BigInt(i - 1) * dp[j]) % MOD;
        }
        dp = nextDp;
    }
    return Number(dp[k]);
};
